(function exposeToolboxResourceData(root) {
  'use strict';

  const encodedEntryChunks = [
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    // RESOURCE_DATA_CHUNKS
  ];

  function decodeBase64(value) {
    if (typeof Buffer !== 'undefined') {
      return Buffer.from(value, 'base64').toString('utf8');
    }
    const binary = root.atob(value);
    const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  }

  const resourceData = JSON.parse(decodeBase64(encodedEntryChunks.join('')));
  root.ToolboxResourceData = resourceData;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = resourceData;
  }
}(typeof window !== 'undefined' ? window : globalThis));
